"""QA 240 D repro (generated by tools/qa/qa_d_core.py). Signature: stderr|marking/modal.py:153|TypeError: Converting py args to operator properties: enum "GeometryNodeTree" not found in ('OUTLINE

Run: ALLSET_SANDBOX=qa_d python tests/run.py --no-build -k __none__ --extra tools/qa/repro_d_3_108.py
"""
from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path

_spec = spec_from_file_location('qa_d_core', Path(__file__).resolve().parent / 'qa_d_core.py')
core = module_from_spec(_spec)
_spec.loader.exec_module(core)

ACTIONS = [
 {
  "kind": "menu",
  "path": "Windows/Bifrost Graph Editor",
  "w": 1
 }
]
SIGNATURE = "stderr|marking/modal.py:153|TypeError: Converting py args to operator properties: enum \"GeometryNodeTree\" not found in ('OUTLINE"


def test_repro():
    mk = core.Monkey()
    mk.run(ACTIONS)
    hits = [f for f in mk.failures if f[1] == SIGNATURE]
    assert not hits, hits[0][2][-1500:]
